import struct
import hashlib
import hmac
import os
import secrets
from typing import Optional, Tuple

# Secure message framing protocol for IoT command relay
# Frame format: [magic:4][version:2][flags:2][payload_len:4][header_ext_len:2][reserved:2][header_ext][payload][mac:32]

MAGIC = b'\x7fCMD'
VERSION = 2
MAX_PAYLOAD_SIZE = 65536
MAX_HEADER_EXT_SIZE = 4096
MAX_FRAME_SIZE = MAX_PAYLOAD_SIZE + MAX_HEADER_EXT_SIZE + 48  # headers + mac

class SecureFrameError(Exception):
    pass

class AuthenticationError(SecureFrameError):
    pass

class FrameSizeError(SecureFrameError):
    pass

class SecureFrameProcessor:
    """Processes authenticated command frames for IoT device relay."""

    def __init__(self, shared_secret: bytes):
        if len(shared_secret) < 32:
            raise ValueError("Shared secret must be at least 32 bytes")
        self.shared_secret = shared_secret
        self._nonce_cache: set = set()
        self._max_nonce_cache = 10000

    def _compute_mac(self, data: bytes) -> bytes:
        """Compute HMAC-SHA256 over frame data."""
        return hmac.new(self.shared_secret, data, hashlib.sha256).digest()

    def _verify_mac(self, data: bytes, expected_mac: bytes) -> bool:
        """Constant-time MAC verification."""
        computed = self._compute_mac(data)
        return hmac.compare_digest(computed, expected_mac)

    def _check_replay(self, nonce: bytes) -> bool:
        """Check if nonce was already seen (replay protection)."""
        if nonce in self._nonce_cache:
            return False
        if len(self._nonce_cache) >= self._max_nonce_cache:
            # Evict oldest entries (simplified)
            self._nonce_cache.clear()
        self._nonce_cache.add(nonce)
        return True

    def parse_frame(self, raw_frame: bytes) -> Tuple[bytes, bytes, int]:
        """Parse and authenticate an incoming frame.

        Returns (header_extension, payload, flags) if valid.
        Raises appropriate exceptions on failure.
        """
        # Minimum frame size: 16 (fixed header) + 32 (mac)
        if len(raw_frame) < 48:
            raise FrameSizeError("Frame too small")

        if len(raw_frame) > MAX_FRAME_SIZE:
            raise FrameSizeError("Frame exceeds maximum size")

        # Parse fixed header
        magic = raw_frame[0:4]
        if magic != MAGIC:
            raise SecureFrameError("Invalid magic bytes")

        version = struct.unpack('>H', raw_frame[4:6])[0]
        if version != VERSION:
            raise SecureFrameError(f"Unsupported version: {version}")

        flags = struct.unpack('>H', raw_frame[6:8])[0]

        # payload_len is an UNSIGNED 32-bit integer
        payload_len = struct.unpack('>I', raw_frame[8:12])[0]
        header_ext_len = struct.unpack('>H', raw_frame[12:14])[0]
        # reserved bytes at [14:16]

        # Security: validate sizes before processing
        if header_ext_len > MAX_HEADER_EXT_SIZE:
            raise FrameSizeError("Header extension too large")

        if payload_len > MAX_PAYLOAD_SIZE:
            raise FrameSizeError("Payload too large")

        # Calculate total expected frame size
        # total_data_len is the combined length of header_ext + payload
        total_data_len = header_ext_len + payload_len
        expected_frame_size = 16 + total_data_len + 32  # fixed_header + data + mac

        if expected_frame_size != len(raw_frame):
            raise FrameSizeError("Frame size mismatch")

        # Verify MAC over everything except the MAC itself
        frame_data = raw_frame[:-32]
        frame_mac = raw_frame[-32:]

        if not self._verify_mac(frame_data, frame_mac):
            raise AuthenticationError("MAC verification failed")

        # Extract header extension and payload
        header_ext = raw_frame[16:16 + header_ext_len]
        payload_start = 16 + header_ext_len
        payload = raw_frame[payload_start:payload_start + payload_len]

        # Check for replay if nonce is in header extension
        if flags & 0x01:  # NONCE_PRESENT flag
            if len(header_ext) < 16:
                raise SecureFrameError("Nonce flag set but header ext too small")
            nonce = header_ext[:16]
            if not self._check_replay(nonce):
                raise AuthenticationError("Replay detected")

        return header_ext, payload, flags

    def create_frame(self, payload: bytes, header_ext: bytes = b'',
                     flags: int = 0) -> bytes:
        """Create an authenticated frame."""
        if len(payload) > MAX_PAYLOAD_SIZE:
            raise FrameSizeError("Payload too large")
        if len(header_ext) > MAX_HEADER_EXT_SIZE:
            raise FrameSizeError("Header extension too large")

        header = struct.pack('>4sHHIHH',
                           MAGIC, VERSION, flags,
                           len(payload), len(header_ext), 0)

        frame_data = header + header_ext + payload
        mac = self._compute_mac(frame_data)
        return frame_data + mac


class CommandRelay:
    """Relays authenticated commands to device subsystems."""

    ALLOWED_COMMANDS = {0x01, 0x02, 0x03, 0x04, 0x05}

    def __init__(self, shared_secret: bytes):
        self.processor = SecureFrameProcessor(shared_secret)
        self._command_buffer = bytearray(MAX_PAYLOAD_SIZE)
        self._pending_commands = []

    def process_incoming(self, raw_frame: bytes) -> Optional[dict]:
        """Process an incoming frame and extract command if valid."""
        try:
            header_ext, payload, flags = self.processor.parse_frame(raw_frame)
        except SecureFrameError as e:
            return {"status": "error", "reason": str(e)}

        if len(payload) < 4:
            return {"status": "error", "reason": "Payload too short for command"}

        cmd_id = struct.unpack('>I', payload[0:4])[0]

        if cmd_id not in self.ALLOWED_COMMANDS:
            return {"status": "error", "reason": "Unknown command"}

        cmd_data = payload[4:]

        # Store in command buffer for batch processing
        offset = len(self._pending_commands) * 256
        if offset + len(cmd_data) <= len(self._command_buffer):
            self._command_buffer[offset:offset + len(cmd_data)] = cmd_data
            self._pending_commands.append({
                "cmd_id": cmd_id,
                "offset": offset,
                "length": len(cmd_data),
                "flags": flags
            })

        return {"status": "accepted", "cmd_id": cmd_id}
